package rules; import packet.PacketMetadata; public final class RuleMatcher{public boolean matchesMetadata(IdsRule r,PacketMetadata p){if(r==null||p==null)return false;if(!r.protocol().equals("ip")&&!r.protocol().equals(p.protocol()))return false;boolean fwd=r.source().matches(p.sourceIp())&&r.destination().matches(p.destinationIp())&&r.sourcePort().matches(p.sourcePort())&&r.destinationPort().matches(p.destinationPort());if(r.direction().equals("<>")){boolean rev=r.source().matches(p.destinationIp())&&r.destination().matches(p.sourceIp())&&r.sourcePort().matches(p.destinationPort())&&r.destinationPort().matches(p.sourcePort());return fwd||rev;}return fwd;}}
